/// <summary>
/// NS Zelinka 29.02.24
/// </summary>
/// <param name="sender">FormControl</param>
/// <param name="e">FormControlEventArgs</param>
[FormControlEventHandler(formControlStr(ProjParameters, AVAProdProjects_AVAPPTemplate), FormControlEventType::Lookup)]
public static void AVAProdProjects_AVAPPTemplate_OnLookup(FormControl sender, FormControlEventArgs e)
{
    SysTableLookup          sysTableLookup  = SysTableLookup::newParameters(tableNum(Hierarchy),sender);
    Query                   query           = new Query();
    QueryBuildDataSource    qbdsHierarchy   = query.addDataSource(tableNum(Hierarchy));
    QueryBuildRange         qbrTemplate     = qbdsHierarchy.addRange(fieldNum(Hierarchy, IsTemplate));
    QueryBuildRange         qbrType         = qbdsHierarchy.addRange(fieldNum(Hierarchy, HierarchyType));

    qbrTemplate.value(  queryValue(NoYes::Yes));
    qbrType.value(      queryValue(HierarchyType::Project));

    sysTableLookup.parmQuery(query);

    sysTableLookup.addLookupfield(fieldNum(Hierarchy, Name));
    sysTableLookup.addLookupfield(fieldNum(Hierarchy, Description));
    sysTableLookup.addLookupfield(fieldNum(Hierarchy, HierarchyId));
    sysTableLookup.performFormLookup();

    FormControlCancelableSuperEventArgs cancelSuperEventArgs = e as FormControlCancelableSuperEventArgs;
    cancelSuperEventArgs.CancelSuperCall();
}

